#define SIN_SCALE 0.1f
#define TIME_SCALE 0.5f  // Controls the speed of wobble
#define WAVE_COUNT 1     // More sine waves to make the wobble more complex

// Simple random noise function
float random(vec2 p)
{
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    vec2 wobble = vec2(0.0);
    for (int i = 0; i < WAVE_COUNT; i++) {
        float sine = sin(iTime * TIME_SCALE + float(i) * 3.14 + uv.y * 5.0);
        wobble.x += sin(sine + uv.x * 10.0) * SIN_SCALE * float(i + 1);
        //wobble.y += cos(sine + uv.y * 15.0) * SIN_SCALE * float(i + 1);
    }

    //wobble += random(uv + iTime) * 0.02;

    vec2 modUv = uv + wobble;

    // Output the texture with the new, distorted UV coordinates
    fragColor = texture(iChannel0, modUv);
}
